package io.knowledgebrain.learning;
import java.util.*;import java.time.*;
import org.junit.jupiter.api.*;import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;
import org.flywaydb.core.Flyway;import org.postgresql.ds.PGSimpleDataSource;import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.web.server.ResponseStatusException;import static org.junit.jupiter.api.Assertions.*;
import io.knowledgebrain.contracts.learning.roadmaprating.v1.*;
@EnabledIfEnvironmentVariable(named="BRAIN_TEST_LEARNING_DATABASE_URL",matches=".+")
class RoadmapRatingStoreIntegrationTest {
 RoadmapRatingStore store;PublicRoadmapStore publicStore;PGSimpleDataSource ds;JdbcTemplate sql;UUID space,author,reviewer,voter;UuidV7 ids;String trace="a".repeat(32);
 @BeforeEach void setup(){ds=new PGSimpleDataSource();ds.setURL(System.getenv("BRAIN_TEST_LEARNING_DATABASE_URL"));ds.setUser("brain_learning");ds.setPassword(System.getenv("BRAIN_TEST_LEARNING_DATABASE_PASSWORD"));Flyway.configure().dataSource(ds).locations("classpath:db/migration").load().migrate();publicStore=new PublicRoadmapStore(ds,Clock.systemUTC());store=new RoadmapRatingStore(ds,publicStore,Clock.systemUTC());sql=new JdbcTemplate(ds);ids=new UuidV7(Clock.systemUTC());space=ids.next();author=ids.next();reviewer=ids.next();voter=ids.next();}
 PublicRoadmapStore.Roadmap publish(String title){var p=publicStore.submit(space,author,null,0,title,"","Explicit",PublicRoadmapStoreIntegrationTest.graph(),trace);publicStore.review(space,p.contributionId(),reviewer,1,"APPROVED","Checked",trace);publicStore.merge(space,p.contributionId(),reviewer,2,trace);return publicStore.get(space,p.roadmapId());}
 void update(PublicRoadmapStore.Roadmap v){var p=publicStore.submit(space,author,v.roadmapId(),v.version(),"Updated","","Explicit",PublicRoadmapStoreIntegrationTest.edit(v),trace);publicStore.review(space,p.contributionId(),reviewer,1,"APPROVED","Checked",trace);publicStore.merge(space,p.contributionId(),reviewer,2,trace);}
 void status(int code,org.junit.jupiter.api.function.Executable action){assertEquals(code,assertThrows(ResponseStatusException.class,action).getStatusCode().value());}
 int events(UUID id){return sql.queryForObject("SELECT count(*) FROM outbox_event WHERE aggregateid=?",Integer.class,id);}
 @Test void oneVoteIsMutableRetirableAndReactivatedWithStableIdImmutableAuditAndExactEvent()throws Exception{var root=publish("Rating lifecycle");var original=publicStore.history(space,root.roadmapId(),Long.MAX_VALUE,10);assertNull(store.mine(space,root.roadmapId(),voter).rating());assertEquals(0,store.summary(space,root.roadmapId()).ratingCount());assertNull(store.summary(space,root.roadmapId()).averageScore());var first=store.change(space,root.roadmapId(),voter,0,1,4,false,trace).rating();assertEquals(7,first.ratingId().version());assertEquals(1,first.version());assertEquals("4.00",store.summary(space,root.roadmapId()).averageScore());assertEquals(List.of(0L,0L,0L,1L,0L),store.summary(space,root.roadmapId()).starCounts());assertEquals(first,store.change(space,root.roadmapId(),voter,1,1,4,false,trace).rating());assertEquals(1,events(first.ratingId()));status(412,()->store.change(space,root.roadmapId(),voter,0,1,4,false,trace));var second=store.change(space,root.roadmapId(),voter,1,1,5,false,trace).rating();var retired=store.change(space,root.roadmapId(),voter,2,0,0,true,trace).rating();assertEquals("RETIRED",retired.state());assertEquals(0,store.summary(space,root.roadmapId()).ratingCount());assertEquals(retired,store.change(space,root.roadmapId(),voter,3,0,0,true,trace).rating());var restored=store.change(space,root.roadmapId(),voter,3,1,2,false,trace).rating();assertEquals(first.ratingId(),restored.ratingId());assertEquals(4,restored.version());assertEquals(4,events(first.ratingId()));assertEquals(original,publicStore.history(space,root.roadmapId(),Long.MAX_VALUE,10));assertEquals(first,store.history(space,root.roadmapId(),voter,2,5).getFirst().snapshot());assertEquals(List.of(4L,3L,2L,1L),store.history(space,root.roadmapId(),voter,Long.MAX_VALUE,5).stream().map(RoadmapRatingStore.Revision::version).toList());assertTrue(store.history(space,root.roadmapId(),reviewer,Long.MAX_VALUE,5).isEmpty());var bytes=sql.queryForObject("SELECT payload FROM outbox_event WHERE aggregateid=? AND type='RoadmapRatingCreated'",byte[].class,first.ratingId());var env=RoadmapRatingEnvelopeV1.parseFrom(bytes);var payload=RoadmapRatingChangedV1.parseFrom(env.getPayload());assertEquals(trace,env.getTraceId());assertEquals(voter.toString(),env.getActorId());assertEquals(first.ratingId().toString(),env.getAggregateId());assertEquals("RoadmapRating",env.getAggregateType());assertEquals(4,payload.getScore());assertEquals(1,payload.getRoadmapVersion());assertEquals(first.updatedAt(),payload.getUpdatedAt());assertEquals(store.history(space,root.roadmapId(),voter,2,1).getFirst().revisionId().toString(),payload.getRevisionId());}
 @Test void graphUpdatesExcludeOldVersionWithoutErasingVoteAndExplicitReratingIsRequired(){var root=publish("Version pins");var first=store.change(space,root.roadmapId(),voter,0,1,5,false,trace).rating();update(root);assertEquals(0,store.summary(space,root.roadmapId()).ratingCount());assertEquals(2,store.summary(space,root.roadmapId()).roadmapVersion());assertEquals(first,store.mine(space,root.roadmapId(),voter).rating());assertEquals(2,store.mine(space,root.roadmapId(),voter).currentRoadmapVersion());status(409,()->store.change(space,root.roadmapId(),voter,1,1,3,false,trace));var updated=store.change(space,root.roadmapId(),voter,1,2,3,false,trace).rating();assertEquals(first.ratingId(),updated.ratingId());assertEquals("3.00",store.summary(space,root.roadmapId()).averageScore());assertEquals(1,store.history(space,root.roadmapId(),voter,2,1).getFirst().snapshot().roadmapVersion());}
 @Test void originalPublisherAndPrivateUnpublishedForeignTargetsAreRejected(){var root=publish("Eligibility");assertFalse(store.mine(space,root.roadmapId(),author).canRate());status(403,()->store.change(space,root.roadmapId(),author,0,1,5,false,trace));status(403,()->store.change(space,root.roadmapId(),author,0,0,0,true,trace));status(404,()->store.summary(author,root.roadmapId()));status(404,()->store.change(author,root.roadmapId(),voter,0,1,5,false,trace));var privateRoot=new RoadmapStore(ds,Clock.systemUTC()).create(space,author,"Private","",trace);status(404,()->store.change(space,privateRoot.roadmapId(),voter,0,1,4,false,trace));var pending=publicStore.submit(space,author,null,0,"Unpublished","","Reason",PublicRoadmapStoreIntegrationTest.graph(),trace);status(404,()->store.change(space,pending.roadmapId(),voter,0,1,4,false,trace));for(int score:new int[]{0,6})status(400,()->store.change(space,root.roadmapId(),voter,0,1,score,false,trace));assertEquals(0,sql.queryForObject("SELECT count(*) FROM roadmap_rating WHERE roadmap_id=?",Integer.class,root.roadmapId()));}
 @Test void concurrentFirstRatingHasOneWinnerAndFailedOutboxRollsBack()throws Exception{var root=publish("Concurrency");try(var pool=java.util.concurrent.Executors.newFixedThreadPool(2)){var gate=new java.util.concurrent.CyclicBarrier(2);var futures=new ArrayList<java.util.concurrent.Future<Boolean>>();for(int score:new int[]{2,5})futures.add(pool.submit(()->{gate.await();try{store.change(space,root.roadmapId(),voter,0,1,score,false,trace);return true;}catch(ResponseStatusException e){assertEquals(412,e.getStatusCode().value());return false;}}));assertNotEquals(futures.get(0).get(),futures.get(1).get());}var prior=store.mine(space,root.roadmapId(),voter).rating();String constraint="rating_test_"+prior.ratingId().toString().replace("-","");sql.execute("ALTER TABLE outbox_event ADD CONSTRAINT "+constraint+" CHECK(aggregateid <> '"+prior.ratingId()+"'::uuid OR type <> 'RoadmapRatingUpdated') NOT VALID");try{assertThrows(RuntimeException.class,()->store.change(space,root.roadmapId(),voter,1,1,prior.score()==1?2:1,false,trace));assertEquals(prior,store.mine(space,root.roadmapId(),voter).rating());assertEquals(1,events(prior.ratingId()));assertEquals(1,store.history(space,root.roadmapId(),voter,Long.MAX_VALUE,10).size());}finally{sql.execute("ALTER TABLE outbox_event DROP CONSTRAINT "+constraint);}}
 @Test void deterministicRankingUsesExactMeanThenCountAndIdWithUnratedLastAndCurrentVersionOnly(){var b=publish("Average tie smaller sample");var a=publish("Average tie larger sample");var c=publish("Lower score");var d=publish("Unrated");store.change(space,a.roadmapId(),voter,0,1,4,false,trace);store.change(space,a.roadmapId(),reviewer,0,1,5,false,trace);store.change(space,a.roadmapId(),ids.next(),0,1,4,false,trace);store.change(space,a.roadmapId(),ids.next(),0,1,5,false,trace);store.change(space,b.roadmapId(),voter,0,1,4,false,trace);store.change(space,b.roadmapId(),reviewer,0,1,5,false,trace);store.change(space,c.roadmapId(),voter,0,1,1,false,trace);var ranking=store.ranking(space,"RATING",100);assertEquals(List.of(a.roadmapId(),b.roadmapId(),c.roadmapId(),d.roadmapId()),ranking.items().stream().map(RoadmapRatingStore.Ranked::roadmapId).toList());assertEquals(List.of(1,2,3,4),ranking.items().stream().map(RoadmapRatingStore.Ranked::rank).toList());assertEquals("4.50",ranking.items().getFirst().averageScore());assertEquals(2,store.ranking(space,"RATING",2).items().size());assertTrue(store.ranking(author,"RATING",100).items().isEmpty());assertEquals(d.roadmapId(),store.ranking(space,"RECENT",100).items().getFirst().roadmapId());store.change(space,c.roadmapId(),ids.next(),0,1,1,false,trace);store.change(space,c.roadmapId(),ids.next(),0,1,1,false,trace);store.change(space,c.roadmapId(),ids.next(),0,1,1,false,trace);store.change(space,c.roadmapId(),ids.next(),0,1,1,false,trace);assertEquals(c.roadmapId(),store.ranking(space,"RATING_COUNT",100).items().getFirst().roadmapId());update(a);assertEquals(0,store.ranking(space,"RATING",100).items().stream().filter(v->v.roadmapId().equals(a.roadmapId())).findFirst().orElseThrow().ratingCount());assertEquals("REVIEWED",publicStore.get(space,a.roadmapId()).verification());}
}
